{
    "predictors": [
        {
            "name": "Patent Innovation Intensity",
            "construction": "Number of new patents granted in the past year divided by total assets.",
            "rationale": "Firms with higher patenting activity relative to their size may be more innovative and possess better growth prospects.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Growth Rate",
            "construction": "Annual percentage change in the number of employees reported by the firm.",
            "rationale": "Rapidly expanding workforce may indicate strong business growth and future revenue increases.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Customer Concentration Risk",
            "construction": "Revenue from the top 3 customers divided by total revenue.",
            "rationale": "Firms with diversified customer bases are less vulnerable to losing key clients, indicating stability.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Board Independence Ratio",
            "construction": "Number of independent board members divided by total board members.",
            "rationale": "Greater board independence may lead to better governance and decision-making, enhancing shareholder value.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Operational Efficiency Change",
            "construction": "Recent change in operating margin over the past year.",
            "rationale": "Improvements in operational efficiency can signal enhanced profitability and competitive advantage.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "ESG Controversy Score",
            "construction": "Negative news incidents related to environmental, social, and governance issues over the past year.",
            "rationale": "Lower controversy scores indicate stronger ESG practices, which may reduce risk and improve reputation.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Supply Chain Diversity Index",
            "construction": "Herfindahl-Hirschman Index of supplier expenditures.",
            "rationale": "Diverse supply chains reduce dependency on single suppliers, mitigating risk and ensuring stability.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "R&D Expense Growth",
            "construction": "Year-over-year percentage change in research and development expenditure.",
            "rationale": "Increased investment in R&D could lead to future product innovations and enhanced market positions.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Social Media Sentiment Score",
            "construction": "Net sentiment score from social media mentions over the past quarter, normalized by total mentions.",
            "rationale": "Positive social media sentiment can reflect good consumer perception and potential demand growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Insider Trading Activity",
            "construction": "Net shares bought by insiders over the past year divided by total shares outstanding.",
            "rationale": "Insider buying suggests that management has confidence in the firm's future prospects and undervaluation.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
